     * validation errors so that only well‑formedness (fatal) errors cause failure.
     * Afterwards, the file is parsed using a secure DocumentBuilder.
     *
     * @param configPath path to the XML configuration file
     * @return parsed Document object
     * @throws IOException              if the file cannot be read
     * @throws SAXException             if the XML is not well‑formed
     * @throws ParserConfigurationException if a DocumentBuilder cannot be created
     * @throws IllegalArgumentException    if the path is null or blank
     */
    public Document loadConfig(String configPath) throws IOException, SAXException, ParserConfigurationException {
        if (configPath == null || configPath.isBlank()) {
            throw new IllegalArgumentException("configPath must not be null or empty");
        }

        File configFile = new File(configPath);
        if (!configFile.exists()) {
            throw new IOException("Configuration file not found: " + configPath);
        }

        // Step 1: Validate well-formedness using SchemaFactory + Validator
        SchemaFactory factory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
        // A minimal dummy XSD that allows us to create a Validator.
        // The ErrorHandler will ignore non‑fatal errors, so only fatal well‑formedness errors will surface.
        String dummyXsd = "<?xml version=\"1.0\"?>\n" +
                "<xsd:schema xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\">\n" +
                "    <xsd:element name=\"dummy\" type=\"xsd:string\"/>\n" +
                "</xsd:schema>";
        try {
            Schema schema = factory.newSchema(new StreamSource(new java.io.StringReader(dummyXsd)));
            Validator validator = schema.newValidator();
            validator.setErrorHandler(new ErrorHandler() {
                @Override
                public void warning(SAXParseException exception) {
                    // ignore warnings
                }

                @Override
                public void error(SAXParseException exception) {
                    // ignore non-fatal validation errors (we only want well-formedness)
                }

                @Override
                public void fatalError(SAXParseException exception) throws SAXException {
                    // rethrow fatal errors, which include well-formedness violations
                    throw exception;
                }
            });
            validator.validate(new StreamSource(configFile));
        } catch (SAXException e) {
            // wrap to preserve original message
            throw new SAXException("XML validation failed (not well-formed): " + e.getMessage(), e);
        }

        // Step 2: Parse into a DOM Document with secure settings
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // Disable external entities, DTDs, and external parameter entities to prevent XXE
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);

        DocumentBuilder builder = dbf.newDocumentBuilder();
        return builder.parse(configFile);
    }
}
